    'use strict'
    myApp.controller("mainctrl", ['$scope', 'shareData', 'cache', '$rootScope', 'ajax', '$location', 'utilFunctions', '$window', '$q', '$compile', '$timeout', 'validations', 'FormSubmitter', 'NgTableParams', '$filter', 'constants', function ($scope, shareData, cache, $rootScope, ajax, $location, utilFunctions, $window, $q, $compile, $timeout, validations, FormSubmitter, NgTableParams, $filter, constants) {
        /* 
            @alert: Code common to all functions can only be written"
          */
        //language 
        //$scope.validations=validations;
        $rootScope.timelimit = 5000;
        $scope.dtflag = false;
        $scope.dupInvNo = shareData.dupInvNo;
        $scope.conerr = false;
        $scope.gt_man = false;
        $scope.uploadflag = false;
        $scope.cnt = null;
        var dateFormat = $().getConstant('DATE_FORMAT') || 'DD/MM/YYYY';
        $scope.connerrmsg = "Unable to connect to server due to some technical issue";
        utilFunctions.initCache();
        if(localStorage.getItem('countergstr3b')=='Y'){
            localStorage.removeItem('countergstr3b');
        }
        var HSN_BIFURCATION_START_DATE = $().getConstant('HSN_BIFURCATION_START_DATE');
        $scope.servers = $().getServers();
        
        var  dropdown={
                    "data":{
                        "values":[
                        {
                                        "qurtr": "April-June",
                                        "value": "062020"
                                      },
                                     {
                                        "qurtr": "July-Sept",
                                        "value": "092020"
                                      },
                                     {
                                        "qurtr": "Oct-Dec",
                                        "value": "122020"
                                      },
                                      {
                                        "qurtr": "Jan-Mar",
                                        "value": "032021"
                                      }
                        ]
                    }
                };
                $scope.qurtr = dropdown.data.values;
            $scope.frmqrtr = $scope.qurtr[0];
            $scope.toqrtr = $scope.qurtr[$scope.qurtr.length - 1];
        //added for masking changes CR17153
        if ($().getConstant(constants.COMP_REPORT_FLAG)){
            $scope.compFlag = $().getConstant(constants.COMP_REPORT_FLAG);
        };
        $scope.trans = utilFunctions.initLanguage('returns');
        $rootScope.$on("LangChanged", function (event, mass) {
            $scope.trans = utilFunctions.initLanguage('returns');
        });
    
        $scope.$on('$viewContentLoaded', function () {
            $window.scrollTo(0, 0);
            angular.element(document.querySelector('[autofocus]')).focus();
        });
        
         $scope.formatDate = function (e, ui) {
            var d = e;
            if(d == "" || d== null || d==undefined){
                return;
            }
            if (d !== null && d !== "" && d.match(new RegExp("((0[1-9]|[12][0-9]|3[01])[/](0[1-9]|1[012])[/]((19|20)\\d\\d))")) !== null && ui === 1) {
                e = d.replace(new RegExp("((0[1-9]|[12][0-9]|3[01])[/](0[1-9]|1[012])[/]((19|20)\\d\\d))"), "$2-$3-$4");
                return e;
            } else if (d !== null && d !== "" && d.match(new RegExp("((0[1-9]|[12][0-9]|3[01])[-](0[1-9]|1[012])[-]((19|20)\\d\\d))")) !== null && ui === 0) {
                e = d.replace(new RegExp("((0[1-9]|[12][0-9]|3[01])[-](0[1-9]|1[012])[-]((19|20)\\d\\d))"), "$2/$3/$4");
                return e;
            } else {
                return d;
            }
            };
    
        $scope.disable_btn = function (stat) {
            if (shareData.fil_stat == 'FRZ' || shareData.fil_stat == 'FIL' || shareData.fil_stat == 'IP' || shareData.fil_stat == 'REC' || stat == 'IP' || stat == 'REC' || stat === 'FIL' || stat === 'FRZ') {
                return true;
            } else {
                return false;
            }
        };
        
        $scope.disable_btn_file = function (stat) {
            if (shareData.fil_stat === 'FIL' || shareData.fil_stat === 'IP' || shareData.fil_stat === 'REC' || stat==='FIL' || shareData.fil_stat == 'F') {
                return true;
            } else {
                return false;
            }
        };
        $scope.gstr2_disable_btn = function (stat) {
            if (shareData.filing_stat == 'FRZ' || shareData.filing_stat == 'FIL' || stat == 'IP' || stat == 'REC') {
                return true;
            } else {
                return false;
            }
        };
    
        $scope.disable_btn1 = function (stat) {
            if (shareData.fil_stat == 'FRZ') {
                return false;
            } else {
                return true;
            }
        };
    
        $scope.gstr2_disable_btn1 = function (stat) {
            if (shareData.filing_stat == 'FRZ') {
                return false;
            } else {
                return true;
            }
        };
        
        //GSTR5 Submit Disable Function 
        $scope.gstr5_disable_btn = function (stat) {
            if (shareData.filing_stat == 'FRZ' || shareData.filing_stat == 'FIL' || stat == 'IP' || stat == 'REC') {
                return true;
            } else {
                return false;
            }
        };
    
        //closes the confirmation modal which appears on clicking the delete button
        $scope.destroyModal = function () {
            utilFunctions._destroyDialogue();
            $('body').css('padding-right', 0);
        };
    
        $scope.checkItemAmount = function (item, supType) {
            if (supType == 'Intra-State') {
                if ((item.camt == 0 && item.crt == 0 && item.samt == 0 && item.srt == 0) || (item.camt > 0 && item.crt > 0 && item.samt > 0 && item.srt > 0)) {
                    return true;
    
                } else {
                    return false;
                }
            } else {
                return true;
            }
        }
    
    
        $rootScope.$on("CallGSTR", function (event, res, gstr1type) {
            shareData.rtn_prd = res.finYear;
             shareData.fil_stat=res.status;
           shareData.arnForItc=res.arn;
           localStorage.setItem("BCK_FLAG", "E");
            localStorage.setItem("rtn_prd", ""+shareData.rtn_prd);
           if (gstr1type == 'GSTR1') {
        	   $window.location.href = '/returns/auth/gstr1';
           }else if (gstr1type == 'GSTR1E') {
               $location.path('auth/gstr1ex');
           }
            else if (gstr1type == 'GSTR2') {
               $location.path('auth/gstr2');
           } else if (gstr1type == 'GSTR3') {
               $location.path('auth/gstr3');
           } 
           else if (gstr1type == 'GSTR4') {
              $window.location.href='/returns2/auth/gstr4';
           }else if (gstr1type == 'GSTR5') {
        	   $window.location.href = '/returns/auth/gstr5';
           } else if (gstr1type == 'GSTR2A') {
               $location.path('auth/gstr2A');
           } else if (gstr1type == 'GSTR8') {
               $location.path('auth/gstr8');
           } else if (gstr1type == 'GSTR6') {
               $location.path('auth/gstr6');
            } else if (gstr1type == 'GSTR7') {
               $window.location.href='/returns2/auth/gstr7';
            }else if (gstr1type == 'GSTR9') {
                $window.location.href = '/returns2/auth/gstr9/dashboard';
           }
            else if (gstr1type == 'GSTR9A') {
                $window.location.href='/returns2/auth/gstr9a';
            }
             else if (gstr1type == 'GSTR9C') {
                $window.location.href = '/returns2/auth/gstr9c/dashboard';
            }
            else if (gstr1type == 'GSTR2X') {
                localStorage.setItem('BCK_FLAG','EFILE');
                $window.location.href = '/returns2/auth/gstr2x';
            
        }
            else if (gstr1type == 'GSTR11') {
               $window.location.href='/returns2/auth/gstr11';
           }
            else if (gstr1type == 'GSTR5A') {
               localStorage.setItem("rtn_prd", ""+shareData.rtn_prd);
               localStorage.setItem("FILSTATUS", shareData.fil_stat);
                 $window.location.href="/returns2/auth/gstr5a";
               //$location.path('/returns2/auth/gstr5a');
           } 
           else if (gstr1type == 'GSTR3B') {
               var quarEnablePrd = $scope.servers.RTN_PROFILE_QOQ_SQ ? $scope.servers.RTN_PROFILE_QOQ_SQ : "012021";
                var mon = Number(quarEnablePrd.substring(0, 2)) - 1;
                var yr = Number(quarEnablePrd.substring(2, 6));
                var gstr3BQuarterlyLiveDate = new Date(yr, mon);  // october 2020
                var userRtnPrd = new Date(Number(shareData.rtn_prd.substring(2, 6)), Number(shareData.rtn_prd.substring(0, 2)) - 1);
                var enableGstr3bQuarterly = userRtnPrd >= gstr3BQuarterlyLiveDate ? true : false;
                localStorage.setItem("enableGstr3bQuarterly", enableGstr3bQuarterly);
                //$location.path('auth/gstr3b');
                localStorage.setItem("GSTR3b_Info", "Y");
                // Setting up the user profile frequency
                localStorage.setItem("uPref", res.userPref);
                var pref = (enableGstr3bQuarterly && res.userPref == "Q") ? "Q" : "M";
                localStorage.setItem("gstr3bPref", pref);
                FormSubmitter.submit("auth/gstr3b", "POST", {
                    "RTN_PRD": shareData.rtn_prd
                });
           }
           else if (gstr1type == 'TRAN1') {
               $window.location.href='/returns/auth/transition/trans1';
           }
            else if (gstr1type == 'TRAN2') {
                localStorage.setItem("tran2dashboardflag",true);
    
            $window.location.href='/returns/auth/transition/trans2';
           }
            else if (gstr1type == 'TRAN3') {
          $window.location.href='/returns/auth/transition/trans3';
           }
            else if (gstr1type == 'ITC01-18A') {
              localStorage.setItem("ARNITC",shareData.arnForItc+"");
                localStorage.setItem("RETTYPEITC","ITC01-18A");
                localStorage.setItem("FY",res.fy+"");
               $window.location.href='/returns2/auth/itcform/itc01summ';
           }
           else if (gstr1type == 'ITC01-18B') {
