/*jslint browser: true*/
/*global $, jQuery, angular*/
/*   @author:    Mohammed Aftab, Amrita Dubey, Shruti Kiranagi,Manali Reddy
    @created:   Sep-Nov 2016
    @description: 
    @description: this is for "Credit/Debit Notes"	
    @copyright: (c) Copyright by Infosys technologies
  */
'use strict';
var myApp = angular.module("myApp", ['ngRoute', 'LocalStorageModule', 'ngProgress','ngTable','angularjs-dropdown-multiselect']);
myApp.value('version', "1.1");
myApp.value('servers', true);
myApp.config(function($logProvider, $provide){

    // $logProvider.debugEnabled(true);
    var EnableLog = true;

    $provide.decorator('$log', function ($delegate) {
        //Original methods
        var origInfo = $delegate.info;
        var origLog = $delegate.log;

        //Override the default behavior
        var logTypes = ['log', 'warn', 'info', 'error', 'debug'],
            logTypLen = logTypes.length;

        for(var i=0;i<logTypLen;i++){
            $delegate[logTypes[i]] = function () {
                if (EnableLog)
                origInfo.apply(null, arguments)
            };
        }

        return $delegate;
    });
});
//maintrunk
var RouteProviderConfig = function ($routeProvider, $locationProvider) {
    var returnVerion = $().getConstant('GST_RETURN_VER');
	var ServiceURL =$().getServers().GST_SERVICES_R1_URL;
    if($().getConstant('IFF_GO_LIVE_RTN_PRD')){
        var IFFEnabled = $().getConstant('IFF_GO_LIVE_RTN_PRD');
        var IFFret_period=localStorage.getItem('rtn_prd');
        var Iff_go_live_prd = localStorage.getItem('IFF_GO_LIVE_PRD');
        if(Iff_go_live_prd == null && IFFret_period != null){
            IFFEnabled = Number(IFFEnabled.substring(2)+IFFEnabled.substring(0,2));
            var IFFreturnperiod = Number(IFFret_period.substring(2)+IFFret_period.substring(0,2))
            if(IFFreturnperiod>=IFFEnabled)
            localStorage.setItem('IFF_GO_LIVE_PRD',true);
            else localStorage.setItem('IFF_GO_LIVE_PRD',false);
        }
        var Iff_go_live_prd = localStorage.getItem('IFF_GO_LIVE_PRD');
    }
    $routeProvider
    
    /*********************************************************GSTR-1********************************************************************/
       
        .when('/auth/dashboard', {
            templateUrl: '/pages/returns/dashboard.html',
            controller: 'dashboardcrtl',
            bc: [{
                "n": "Returns",
                "u": "returns/auth/dashboard"
            }]
        }).when('/auth/gstr/ewbofflinedownload', {
            templateUrl: '/pages/returns/ewb/ewbdownload.html',
            controller: 'gstr1Ewbctrl',
            bc: [{
                "n": "Returns",
                "u": "returns/auth/dashboard"
            }, {
                "n": "EWBGSTR-1",
                "u": ""
            }]
        }).when('/auth/finalreturn',{
            templateUrl:'/pages/returns/finalreturn.html',
            controller:'gstr10ctrl',
            bc: [{
                "n": "Final Return",
