    myApp.controller("dashboardcrtl", ['$scope', '$location', '$rootScope', 'shareData', '$timeout', '$window', 'version', 'cache', 'ajax', '$compile', "$route", '$http', '$filter', '$log', 'utilFunctions', 'FormSubmitter', function ($scope, $location, $rootScope, shareData, $timeout, $window, version, cache, ajax, $compile, $route, $http, $filter, $log, utilFunctions, FormSubmitter) {
        sessionStorage.clear();
        if ($().getConstant("rtn_prd")) {
            localStorage.setItem('rtn_prd', $().getConstant("rtn_prd"));
        }
        if ($().getConstant("bck_flag")) {
            localStorage.setItem('BCK_FLAG', $().getConstant("bck_flag"));
        }
        if ($().getConstant("formname")) {
            localStorage.setItem('formname', $().getConstant("formname"));
        }
        if ($().getConstant("IFF_GO_LIVE_RTN_PRD")) {
            localStorage.setItem('IFF_GO_LIVE_RTN_PRD', $().getConstant("IFF_GO_LIVE_RTN_PRD"));
        }
        if ($().getConstant("ECO_SUP_STRT_PRD")) {
            localStorage.setItem('ECO_SUP_STRT_PRD', $().getConstant("ECO_SUP_STRT_PRD"));
        }
        else localStorage.setItem('ECO_SUP_STRT_PRD', "062021");
   
        $scope.showMessage = false;    
        $scope.periodToDisplay = function(fmnth,fyr) {
            $scope.year = null;
            if(fmnth["value"].slice(0, 2) != '16'){
                $scope.year= fmnth["value"].slice(-4);
            } else {
            $scope.year= fyr["year"].slice(0,2) + fyr["year"].slice(-2);
            }
            return fmnth["month"] + ' ' + $scope.year; 
        }
        
        $scope.notifiedForms= [];
        $scope.showBarredMsg = function(rtyp,fmnth,fyr,sbtyp) {
            $scope.warningcontent= [];
            rtyp = $scope.getSubType(rtyp,sbtyp);
            if (!$scope.notifiedForms.includes(rtyp)) { 
            $scope.notifiedForms.push(rtyp);
            }
            $scope.yearToDisplay = null;
            $scope.yearToDisplay = $scope.periodToDisplay(fmnth,fyr);
            var sentence1 = $scope.notifiedForms.join(' & ');
                var newDiv1 = { content: 'You are not allowed to file '+ sentence1 +' for tax period ' + $scope.yearToDisplay +' after the expiry of ' + $scope.gstr_barredYearsLimit + ' years from the respective due date of filing.'};
                $scope.warningcontent.push(newDiv1);
        $scope.showMessage = true;
        }
        $scope.closeWarningMsg = function () {
            $scope.showMessage = false;
            $scope.notifiedForms=[];
            $scope.warningcontent=[];
        }
        $scope.getSubType = function (rtyp,sbtyp) {
            if(sbtyp!=null && rtyp=="GSTR1" && sbtyp==="IFF")
            {
            rtyp = "Invoice Furnishing Facility (IFF)"  
            }  else {
                rtyp = rtyp.replace(/([a-zA-Z]+)(\d+)/, '$1-$2');
            }
        return rtyp;
        }
     
        $scope.ecoSupFlag = false;
        $scope.compareEcoSup= function(){
            const curr_rtn_prd = localStorage.getItem("rtn_prd");
            const curr_sup_strt_prd = localStorage.getItem("ECO_SUP_STRT_PRD");
            if(!curr_sup_strt_prd || curr_sup_strt_prd== "null")   return;
            const ret_prd_month= curr_rtn_prd.substring(0, 2);
            const ret_prd_year= curr_rtn_prd.substring(2);
            const sup_strt_prd_month= curr_sup_strt_prd.substring(0, 2);
            const sup_strt_prd_year= curr_sup_strt_prd.substring(2);
            if(ret_prd_year > sup_strt_prd_year  || (ret_prd_year == sup_strt_prd_year && ret_prd_month >= sup_strt_prd_month ) ){
                $scope.ecoSupFlag=true;
                shareData.ecoSupFlag= $scope.ecoSupFlag;
        
            }
            
        }
    
        $scope.flag = "";
        $scope.years = [];
        localStorage.removeItem('efile_data');
        $scope.isCmp08 = false;
        $scope.handleMessages = function (iFlag, iType, iMsg) {
    
            if (iFlag) {
    
                $scope.showMsg = true;
                $scope.mType = iType;
                $scope.message = iMsg;
    
            } else {
                $scope.showMsg = false;
            }
        };
        //$scope.msme = {};
    
    
        utilFunctions.initCache();
        $scope.servers = $().getServers();
        $scope.trans = utilFunctions.initLanguage('returns');
        $rootScope.$on("LangChanged", function (event, mass) {
            $scope.trans = utilFunctions.initLanguage('returns');
        });
    
        $scope.$on('$viewContentLoaded', function () {
            $window.scrollTo(0, 0);
            angular.element(document.querySelector('[autofocus]')).focus();
        });
