        var obDetailDates = $scope.servers.RTN_REV_RCLM_OB_DETL.split('|');
        var amendDate = new Date(obDetailDates[1]);
        amendDate.setHours(0, 0, 0, 0);
    
        var now = new Date();
        now.setHours(0, 0, 0, 0);
        if (amendDate >= now) {
            $scope.obPage = true;
        } else {
            $scope.obPage = false;
        }
        //CR-26198 : Ob button validations  (Amended date) 
        var rcmobDetailDates = $scope.servers.RTN_RCM_OB_DETL.split('|');
        var rcmamendDate = new Date(rcmobDetailDates[1]);
        rcmamendDate.setHours(0, 0, 0, 0);
        if (rcmamendDate >= now) {
            $scope.rcmobPage = true;
        } else {
            $scope.rcmobPage = false;
        }
