        //handling of rror messages  
        function handleErrorAlert() {
            switch (shareData.invoiceSaveFlag) {
                case 0:
                    $scope.handleMessages(1, "danger", shareData.dash_fail_msg);
                    break;
                case 1:
                    if ($scope.up_inv_msg) {
                        $scope.handleMessages(1, "success", "Invoices Uploaded successfully" + $scope.up_inv_msg);
                    }
                    break;
                default:
                    $scope.handleMessages(0, null, null);
                    break;
            }
            shareData.invoiceSaveFlag = -1;
        }
    
        // functionality for page navigation.
        $scope.page = function (path) {
            $location.path(path);
        }
    
        //variable initialized
        shareData.subbtn = false;
        //Functionality for generate GSTR-3
        $scope.GenerateButton = function () {
