		if (!val) {
			$scope.suc_msg = false;
			$scope.sub = true;
			shareData.attached = false;
			$scope.caerr = "Please select file to upload";
			return false;
		} else {
			$scope.caerr = "";
			$scope.sub = false;
		}
		if ($scope.caDetails) {
			if ($scope.filing && $scope.filing.$valid) {  /* && $scope.address.$valid */
				if (val) {
					$scope.sub = false;
					$scope.docid = val ? val[0].id : undefined;
					$scope.hashid = val ? val[0].hash : undefined;
					$scope.ty = val ? val[0].ty : undefined;
				} else {
					$scope.docid = shareData.pdfData.docid;
					$scope.hashid = shareData.pdfData.hashid;
					$scope.ty = shareData.pdfData.ty;
				}

				var attachment = [];
				var object1 = {
					docid: $scope.docid,
					caDetails: $scope.caDetails,
					hash: $scope.hashid,
					ty: $scope.ty
				}
				attachment.push(object1);
				var attach = {
					gstin: shareData.gstr10_gstin,
					fp: shareData.gstr10_fp,
					//addr:$scope.addrss,
					attachments: attachment
				};
				ajax.post('/returns2/auth/api/gstr10/invoice/add', attach, {},
					function () {
						$().blockPage(true);
					}, function () {
						$().blockPage(false);
					}).then(function (response) {
						if (response.status == 1) {
							shareData.compdata = {
								caDetails: angular.copy($scope.caDetails),
								attachid: attach.docId
							}
							$scope.attachment = response;
							$().blockPage(false);
							$scope.attached = true;
							/* $scope.suc_msg = true;
							$scope.casuc = "Upload is successful."; */
							shareData.attached = true;
							$scope.fail_msg = false;
							$('[name=staus_msg]').empty();
							$window.scrollTo(0, 0);
							$scope.alertmessage("Upload is successful.", 1);
						}
						else if (response.status == 0) {
							$scope.fail_msg = true;
							$scope.suc_msg = false;
							$scope.summaryMsg = response.error.message;
						}
					}, function (err) {
						$scope.alertmessage("Something went wrong. Please try Again", 0);
					});
			} else {
				$scope.suc_msg = false;
				$scope.sub = true;
				shareData.attached = false;
				$scope.camg = "Please save the relevant fields or the document if uploaded new";
			}
		}
	}
