downloadGstr11Excel.body:
downloadGstr11Excel = function () {
        console.log('downloadGstr11Excel');
        var url = '/returns2/auth/api/gstr11/filed/excel';
        var section = 'R11EX';
        $scope.file_type = 'EX';

        if (!$scope.batchDownload) {
            var params = {
                "gstin": shareData.gstin,
                "rtn_prd": shareData.rtn_prd,
                "section": section
            };
            $().blockPage(true);
            $http({ url: url, data: params, params: params, method: 'GET', responseType: 'arraybuffer' }).then(function (response) {
                $().blockPage(false);
                var decodedString = String.fromCharCode.apply(null, new Uint8Array(response.data));
                try {
                    var obj = JSON.parse(decodedString);
                    if (obj.status_cd == 0) {
                        // $scope.handleMessages(1, "success", obj['message']);
                            $scope.downloadExcel();
                            $scope.batchDownload = true;
                        }
                    }
                    catch (err) {
                        let mediatype = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
                        const data = new Blob([response.data], { type: mediatype });
                        if (window.navigator && window.navigator.msSaveOrOpenBlob) {
                            window.navigator.msSaveOrOpenBlob(data, shareData.udata.gstin + "_" + shareData.rtn_prd + "_R6A" + ".xlsx");
                        }
                        else {
                            var objectUrl = URL.createObjectURL(data);
                            var fileLink = document.createElement('a');
                            fileLink.href = objectUrl;
                            fileLink.download = shareData.udata.gstin + "_" + shareData.rtn_prd + "_R11" + ".xlsx";
                            fileLink.click();
                        }
                    }
                }, function (response) {
                    $().blockPage(false);
                    $scope.downloadExcel();
                });
            }
            else{
                $scope.downloadExcel();
            }
        }

