        $scope.conerr = false;
        $scope.gt_man = false;
        $scope.uploadflag = false;
        $scope.cnt = null;
        var dateFormat = $().getConstant('DATE_FORMAT') || 'DD/MM/YYYY';
        $scope.connerrmsg = "Unable to connect to server due to some technical issue";
        utilFunctions.initCache();
        if(localStorage.getItem('countergstr3b')=='Y'){
            localStorage.removeItem('countergstr3b');
        }
        var HSN_BIFURCATION_START_DATE = $().getConstant('HSN_BIFURCATION_START_DATE');
        $scope.servers = $().getServers();
        
