                                      },
                                     {
                                        "qurtr": "July-Sept",
                                        "value": "092020"
                                      },
                                     {
                                        "qurtr": "Oct-Dec",
                                        "value": "122020"
                                      },
                                      {
                                        "qurtr": "Jan-Mar",
                                        "value": "032021"
                                      }
                        ]
                    }
                };
                $scope.qurtr = dropdown.data.values;
            $scope.frmqrtr = $scope.qurtr[0];
            $scope.toqrtr = $scope.qurtr[$scope.qurtr.length - 1];
        //added for masking changes CR17153
        if ($().getConstant(constants.COMP_REPORT_FLAG)){
            $scope.compFlag = $().getConstant(constants.COMP_REPORT_FLAG);
        };
        $scope.trans = utilFunctions.initLanguage('returns');
        $rootScope.$on("LangChanged", function (event, mass) {
            $scope.trans = utilFunctions.initLanguage('returns');
        });
    
        $scope.$on('$viewContentLoaded', function () {
            $window.scrollTo(0, 0);
            angular.element(document.querySelector('[autofocus]')).focus();
        });
        
         $scope.formatDate = function (e, ui) {
            var d = e;
            if(d == "" || d== null || d==undefined){
                return;
            }
            if (d !== null && d !== "" && d.match(new RegExp("((0[1-9]|[12][0-9]|3[01])[/](0[1-9]|1[012])[/]((19|20)\\d\\d))")) !== null && ui === 1) {
                e = d.replace(new RegExp("((0[1-9]|[12][0-9]|3[01])[/](0[1-9]|1[012])[/]((19|20)\\d\\d))"), "$2-$3-$4");
                return e;
            } else if (d !== null && d !== "" && d.match(new RegExp("((0[1-9]|[12][0-9]|3[01])[-](0[1-9]|1[012])[-]((19|20)\\d\\d))")) !== null && ui === 0) {
                e = d.replace(new RegExp("((0[1-9]|[12][0-9]|3[01])[-](0[1-9]|1[012])[-]((19|20)\\d\\d))"), "$2/$3/$4");
                return e;
            } else {
                return d;
            }
            };
    
        $scope.disable_btn = function (stat) {
            if (shareData.fil_stat == 'FRZ' || shareData.fil_stat == 'FIL' || shareData.fil_stat == 'IP' || shareData.fil_stat == 'REC' || stat == 'IP' || stat == 'REC' || stat === 'FIL' || stat === 'FRZ') {
                return true;
            } else {
                return false;
            }
        };
        
        $scope.disable_btn_file = function (stat) {
            if (shareData.fil_stat === 'FIL' || shareData.fil_stat === 'IP' || shareData.fil_stat === 'REC' || stat==='FIL' || shareData.fil_stat == 'F') {
                return true;
            } else {
                return false;
            }
        };
        $scope.gstr2_disable_btn = function (stat) {
            if (shareData.filing_stat == 'FRZ' || shareData.filing_stat == 'FIL' || stat == 'IP' || stat == 'REC') {
                return true;
            } else {
                return false;
            }
        };
    
        $scope.disable_btn1 = function (stat) {
            if (shareData.fil_stat == 'FRZ') {
                return false;
            } else {
                return true;
            }
        };
    
        $scope.gstr2_disable_btn1 = function (stat) {
            if (shareData.filing_stat == 'FRZ') {
