        };
    
        $scope.checkItemAmount = function (item, supType) {
            if (supType == 'Intra-State') {
                if ((item.camt == 0 && item.crt == 0 && item.samt == 0 && item.srt == 0) || (item.camt > 0 && item.crt > 0 && item.samt > 0 && item.srt > 0)) {
                    return true;
    
                } else {
                    return false;
                }
            } else {
                return true;
            }
        }
    
    
