               $window.location.href='/returns2/auth/itc04/selectquarter';
           }
            else if (gstr1type == 'ITC02') {
               localStorage.setItem("ARNITC",shareData.arnForItc+"");
               localStorage.setItem("ITC02VIEWPATH","true");
               $window.location.href='/returns2/auth/itc02/transfer';
