downloadGSTR3Bpdf.body:
downloadGSTR3Bpdf = function () {
            $scope.inadmInelgITC();
            $().blockPage(true);
            var params = {
                "rtn_prd": shareData.rtn_prd,
                "rtn_typ": "GSTR3B"
            };
            ajax.get("auth/api/formdetails", params).then(function (response) {
                if (response.status === 1) {
                    shareData.formDetails = response.data;
                    //2B-3B Autopopulation - @Vishakha
                    $scope.validateGstr2bRetPrd();
                    //CR 21138 Interest calculation -Sneha
                    $scope.validateInterestRetPrd();
                    if ($scope.valid2Brel2rtnprd || $scope.validInterestRtnPrd) {
                        $scope.pdflglnm = '';
                        $scope.pdftrdnm = '';
                        $scope.pdfarn = '';
                        $scope.pdfarndt = '';
                        $scope.pdfauthSig = '';
                        $scope.pdfdesig = '';
    
                        //CR 21138 changes                     
                        ajax.get("/returns/auth/api/gstr3b/sysint?gstin="+shareData.gstr3bSummary.gstin+"&rtn_prd="+shareData.rtn_prd).then(function (response) {
                            $().blockPage(false);
                            
                            if(response.status === 1){
                                if(response.data){
                                shareData.gstr3bInt = response.data;
                                
                                }
                            }else {
                                            shareData.gstr3bInt = null;
                                        }
                                    }, function (response) {
                                        $().blockPage(false);
                                        //console.log(response);
                        });
                        //CR 21138 changes -End
    
                        ajax.get("/returns/auth/api/gstr3b/getgenpdf?rtn_prd=" + shareData.rtn_prd).then(function (response) {
                            $().blockPage(false);
                            // console.log(response);
                            if (response.status == 1) {
                                shareData.gstr3bSummary = angular.copy(response.data.r3b);
                                $scope.pdflglnm = shareData.pdflglnm = response.data.lglnm;
                                $scope.pdftrdnm = shareData.pdftrdnm = response.data.trdnm;
                                $scope.pdfarn = shareData.pdfarn = response.data.arn;
                                $scope.pdfauthSig = shareData.pdfauthSig = response.data.authSig;
                                $scope.pdfdesig = shareData.pdfdesig = response.data.desig;
                                // console.log(response.data);
                                if (response.data != undefined && response.data.arnDt != undefined && $scope.checkForNull(response.data.arnDt)) {
                                    $scope.pdfarndt = shareData.pdfarndt = response.data.arnDt.replace(/-/g, '/');
                                }
                                $scope.downloadPdf('FIL');
                            } else {
                                shareData.gstr3bSummary = {};
                            }
                        }, function (response) {
                            $scope.errorFlag = shareData.errorFlag = false;
                            $().blockPage(false);
                            // console.log(response);
                        });
                    } else {
                        ajax.get("/returns/auth/api/gstr3b/summary?rtn_prd=" + shareData.rtn_prd).then(function (response) {
                            $().blockPage(false);
                            //console.log(response);
                            if (response.status == 1) {
                                shareData.gstr3bSummary = response.data;
                            } else {
                                shareData.gstr3bSummary = {};
                            }
                            $scope.calculateSummary();
                            $scope.downloadPdf('FIL');
    
                        }, function (response) {
                            $().blockPage(false);
                            //console.log(response);
                        });
                    }
                }
            }, function (response) {
                $log.debug(response);
                var url = $().getServers().GST_SERVICES_R1_URL + "/services/error/system";
                $window.location.href = url;
            });
    
        }

