createGstPdf = function () {
            //CR-21773C changes start
            var gstr3btbl3negvallivedt = $().getConstant('RTN_R3B_TBL3_NEGLIAB_LIVEPRD');
            $scope.gstr3btbl3negval =  (Number(shareData.rtn_prd.substring(2)+shareData.rtn_prd.substring(0,2)) >= Number(gstr3btbl3negvallivedt.substring(2)+gstr3btbl3negvallivedt.substring(0,2))) ? true : false;        
            //CR 21773C changes -End
            var pdfname = 'GSTR3B_' + shareData.gstr3bSummary.gstin + '_' + shareData.rtn_prd + ".pdf";
            var text = ($scope.valid2Brel2rtnprd || $scope.validInterestRtnPrd) ? "  FILED " : "  FINAL ";
    
            //CR 21138 changes 
            if ($scope.valid2Brel2rtnprd && !$scope.validInterestRtnPrd) {
