		}
		if ($scope.caDetails) {
			if ($scope.filing && $scope.filing.$valid) {  /* && $scope.address.$valid */
				if (val) {
					$scope.sub = false;
					$scope.docid = val ? val[0].id : undefined;
					$scope.hashid = val ? val[0].hash : undefined;
					$scope.ty = val ? val[0].ty : undefined;
				} else {
					$scope.docid = shareData.pdfData.docid;
					$scope.hashid = shareData.pdfData.hashid;
					$scope.ty = shareData.pdfData.ty;
				}

