							$scope.attachment = response;
							$().blockPage(false);
							$scope.attached = true;
							/* $scope.suc_msg = true;
							$scope.casuc = "Upload is successful."; */
							shareData.attached = true;
							$scope.fail_msg = false;
							$('[name=staus_msg]').empty();
							$window.scrollTo(0, 0);
							$scope.alertmessage("Upload is successful.", 1);
						}
						else if (response.status == 0) {
							$scope.fail_msg = true;
							$scope.suc_msg = false;
							$scope.summaryMsg = response.error.message;
						}
					}, function (err) {
						$scope.alertmessage("Something went wrong. Please try Again", 0);
					});
			} else {
				$scope.suc_msg = false;
				$scope.sub = true;
				shareData.attached = false;
				$scope.camg = "Please save the relevant fields or the document if uploaded new";
			}
		}
	}
