getPdfData.body:
getPdfData = function(typ, formDetails) {
            if (typ === "EXCEL") {
                shareData.gst2aoff = false;
                shareData.gstrtyp = "GSTR9A";
                if (sessionStorage.getItem("formDetails") !== null) {
                    shareData.fil_status = sessionStorage.getItem("formDetails").status;
                } else {
                    shareData.fil_status = formDetails.status;
                }
                $location.path("auth/gstr9a/offlinedownload");
            } else {
                $().blockPage(true);
                var params = {
                    rtn_prd: shareData.rtn_prd,
                };
                //  /pages/returns/forms.json  auth/api/gstr9a/getpdfsumm
                ajax.get("auth/api/gstr9a/getpdfsumm", params).then(
                    function(response) {
                        $().blockPage(false);
                        if (response.status === 1) {
                            $scope.firstTime = response.data.firstGetFlg;
                            $scope.gstr9ADataPdf = response.data;
                            if (typ === "PDF") {
                                $scope.genratepdf_gstr9a($scope.gstr9ADataPdf, false);
                            } else {
                                $scope.destroyModal();
                                var conf = utilFunctions.createDialogue({
                                    type: $scope.trans.LBL_ERR_3B,
                                    title: $scope.trans.LBL_ERR_3B,
                                    message: "PDF data not available",
                                    cancel_btn_title: $scope.trans.BTN_CLOSE,
                                });
                                $("body").append($compile(conf)($scope));
                                $("#errorDlg").modal("show");
                            }
                        } else {
                            $scope.destroyModal();
                            var conf = utilFunctions.createDialogue({
                                type: $scope.trans.LBL_ERR_3B,
                                title: $scope.trans.LBL_ERR_3B,
                                message: response.error.error_msg,
                                cancel_btn_title: $scope.trans.BTN_CLOSE,
                            });
                            $("body").append($compile(conf)($scope));
                            $("#errorDlg").modal("show");
                        }
                    },
                    function(response) {
                        $().blockPage(false);
                        $log.debug(response);
                        var url =
                            $().getServers().GST_SERVICES_R1_URL + "/services/error/system";
                        $window.location.href = url;
                    }
                );
                if (angular.isUndefined($scope.gstr9AData)) {
                    ajax.get("auth/api/gstr9a/getsummary", params).then(
                        function(response) {
                            $().blockPage(false);
                            if (response.status === 1) {
                                $scope.gstr9AData = response.data;
                            }
                        },
                        function(response) {
                            console.log(response);
                        }
                    );
                }
            }
        }

