    // $logProvider.debugEnabled(true);
    var EnableLog = true;

    $provide.decorator('$log', function ($delegate) {
        //Original methods
        var origInfo = $delegate.info;
        var origLog = $delegate.log;

        //Override the default behavior
        var logTypes = ['log', 'warn', 'info', 'error', 'debug'],
            logTypLen = logTypes.length;

        for(var i=0;i<logTypLen;i++){
            $delegate[logTypes[i]] = function () {
                if (EnableLog)
                origInfo.apply(null, arguments)
            };
        }

        return $delegate;
    });
});
