        	   $window.location.href = '/returns/auth/gstr1';
           }else if (gstr1type == 'GSTR1E') {
               $location.path('auth/gstr1ex');
           }
            else if (gstr1type == 'GSTR2') {
               $location.path('auth/gstr2');
           } else if (gstr1type == 'GSTR3') {
               $location.path('auth/gstr3');
           } 
           else if (gstr1type == 'GSTR4') {
              $window.location.href='/returns2/auth/gstr4';
           }else if (gstr1type == 'GSTR5') {
        	   $window.location.href = '/returns/auth/gstr5';
           } else if (gstr1type == 'GSTR2A') {
               $location.path('auth/gstr2A');
           } else if (gstr1type == 'GSTR8') {
               $location.path('auth/gstr8');
           } else if (gstr1type == 'GSTR6') {
               $location.path('auth/gstr6');
            } else if (gstr1type == 'GSTR7') {
               $window.location.href='/returns2/auth/gstr7';
            }else if (gstr1type == 'GSTR9') {
                $window.location.href = '/returns2/auth/gstr9/dashboard';
           }
            else if (gstr1type == 'GSTR9A') {
                $window.location.href='/returns2/auth/gstr9a';
            }
             else if (gstr1type == 'GSTR9C') {
                $window.location.href = '/returns2/auth/gstr9c/dashboard';
            }
            else if (gstr1type == 'GSTR2X') {
                localStorage.setItem('BCK_FLAG','EFILE');
                $window.location.href = '/returns2/auth/gstr2x';
            
        }
            else if (gstr1type == 'GSTR11') {
               $window.location.href='/returns2/auth/gstr11';
           }
            else if (gstr1type == 'GSTR5A') {
               localStorage.setItem("rtn_prd", ""+shareData.rtn_prd);
               localStorage.setItem("FILSTATUS", shareData.fil_stat);
                 $window.location.href="/returns2/auth/gstr5a";
               //$location.path('/returns2/auth/gstr5a');
           } 
           else if (gstr1type == 'GSTR3B') {
               var quarEnablePrd = $scope.servers.RTN_PROFILE_QOQ_SQ ? $scope.servers.RTN_PROFILE_QOQ_SQ : "012021";
                var mon = Number(quarEnablePrd.substring(0, 2)) - 1;
                var yr = Number(quarEnablePrd.substring(2, 6));
                var gstr3BQuarterlyLiveDate = new Date(yr, mon);  // october 2020
                var userRtnPrd = new Date(Number(shareData.rtn_prd.substring(2, 6)), Number(shareData.rtn_prd.substring(0, 2)) - 1);
                var enableGstr3bQuarterly = userRtnPrd >= gstr3BQuarterlyLiveDate ? true : false;
                localStorage.setItem("enableGstr3bQuarterly", enableGstr3bQuarterly);
                //$location.path('auth/gstr3b');
                localStorage.setItem("GSTR3b_Info", "Y");
                // Setting up the user profile frequency
                localStorage.setItem("uPref", res.userPref);
                var pref = (enableGstr3bQuarterly && res.userPref == "Q") ? "Q" : "M";
                localStorage.setItem("gstr3bPref", pref);
                FormSubmitter.submit("auth/gstr3b", "POST", {
                    "RTN_PRD": shareData.rtn_prd
                });
           }
           else if (gstr1type == 'TRAN1') {
               $window.location.href='/returns/auth/transition/trans1';
