                localStorage.setItem("RETTYPEITC","ITC01-18A");
                localStorage.setItem("FY",res.fy+"");
               $window.location.href='/returns2/auth/itcform/itc01summ';
           }
           else if (gstr1type == 'ITC01-18B') {
